INSERT INTO productos (id, nombre, descripcion_corta, descripcion_larga, precio_unitario) VALUES ('89efb206-2aa6-4e21-8a23-5765e3de1f31', 'Pizza Margarita', 'Clásica pizza con tomate y mozzarella', 'Pizza tradicional con salsa de tomate fresco, queso mozzarella y albahaca', 8.50),('7a9b8c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Pizza Pepperoni', 'Pizza con pepperoni y queso', 'Deliciosa pizza con pepperoni abundante, salsa de tomate y doble mozzarella', 10.50),('b4c5d6e7-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Pizza Hawaiana', 'Piña y jamón', 'Pizza tropical con piña fresca, jamón serrano y queso mozzarella', 9.50),('c6d7e8f9-0a1b-2c3d-4e5f-6a7b8c9d0e1f', 'Pizza Cuatro Quesos', 'Mezcla de quesos especiales', 'Pizza con mozzarella, parmesano, gorgonzola y queso de cabra', 12.00),('d8e9f0a1-2b3c-4d5e-6f7a-8b9c0d1e2f3a', 'Pizza Vegetariana', 'Variedad de vegetales frescos', 'Pizza con pimientos, cebolla, champiñones, aceitunas y tomates cherry', 11.00),('ea1b2c3d-4e5f-6a7b-8c9d-0e1f2a3b4c5d', 'Pizza Napolitana', 'Estilo napolitano tradicional', 'Pizza auténtica con salsa San Marzano, mozzarella di bufala y albahaca fresca', 13.50),('fc3d4e5f-6a7b-8c9d-0e1f-2a3b4c5d6e7f', 'Pizza Barbacoa', 'Carne barbacoa y cebolla caramelizada', 'Pizza con carne barbacoa, cebolla caramelizada, salsa barbacoa y queso', 14.00),('0e4f5a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Pizza Carbonara', 'Crema, bacon y huevo', 'Pizza con crema fresca, bacon crujiente, huevo y parmesano', 11.50);